CREATE TABLE IF NOT EXISTS car_availability (id BINARY(16) PRIMARY KEY, car_id BINARY(16) NOT NULL, start_time DATETIME(6) NOT NULL, end_time DATETIME(6) NOT NULL, CONSTRAINT fk_car_availability_car_id__id FOREIGN KEY (car_id) REFERENCES cars(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS car_photos (id BINARY(16) PRIMARY KEY, car_id BINARY(16) NOT NULL, url VARCHAR(512) NOT NULL, is_primary BOOLEAN DEFAULT FALSE NOT NULL, CONSTRAINT fk_car_photos_car_id__id FOREIGN KEY (car_id) REFERENCES cars(id) ON DELETE RESTRICT ON UPDATE RESTRICT);